import {createFontFidelityScenes} from './font-fidelity-scenes.js';
/** Advanced font scenes. loadBytes receives a URL relative to the sample app. */
export async function createFontScenes(S,{loadBytes=async url=>{const response=await fetch(url);if(!response.ok)throw new Error(`Sample font request failed: ${url} (HTTP ${response.status})`);return new Uint8Array(await response.arrayBuffer());}}={}) {
  const [variableBytes,colorBytes,cffBytes,metricsBytes,variableColorBytes]=await Promise.all(['fonts/RobotoFlex-Variable.woff2','fonts/ColorLayers.ttf','fonts/CFF2-Variable.otf','fonts/VariationMetrics.ttf','fonts/VariationColor.ttf'].map(loadBytes));
  const variable=S.SKTypeface.FromData(variableBytes),color=S.SKTypeface.FromData(colorBytes),cff=S.SKTypeface.FromData(cffBytes),metrics=S.SKTypeface.FromData(metricsBytes),variableColor=S.SKTypeface.FromData(variableColorBytes);
  if(!variable||!color||!cff||!metrics||!variableColor){metrics?.Dispose();variableColor?.Dispose();variable?.Dispose();color?.Dispose();cff?.Dispose();throw new Error('An advanced sample font could not be decoded.');}
  let currentWeight=-1,currentFace=null,cffWeight=-1,currentCff=null,currentPalette=-1,paletteFace=null;
  const getFace=weight=>{weight=Math.min(1000,Math.max(100,Math.round(weight??500)));if(weight!==currentWeight){currentFace?.Dispose();currentFace=variable.Clone(new S.SKFontArguments().SetVariationDesignPosition({wght:weight}));currentWeight=weight;}return currentFace;};
  const getCff=weight=>{weight=Math.min(900,Math.max(100,Math.round(weight??500)));if(weight!==cffWeight){currentCff?.Dispose();currentCff=cff.Clone(new S.SKFontArguments().SetVariationDesignPosition({wght:weight}));cffWeight=weight;}return currentCff;};
  const getPalette=index=>{index=Number(index??0)%2;if(index!==currentPalette){paletteFace?.Dispose();paletteFace=color.Clone(new S.SKFontArguments().SetPalette({Index:index}));currentPalette=index;}return paletteFace;};
  const draw=fn=>(c,w,h,o={})=>{const resources=[],own=v=>(resources.push(v),v);const paint=(hex,stroke=0)=>{const p=own(new S.SKPaint());p.Color=S.SKColor.Parse(hex);p.IsAntialias=true;if(stroke){p.Style=S.SKPaintStyle.Stroke;p.StrokeWidth=stroke;}return p;};const label=(str,x,y,size=16,hex='#ACBDD0')=>{const f=own(new S.SKFont(null,size));c.DrawText(str,x,y,f,paint(hex));};const count=c.Save();try{c.Scale(w/960,h/600);fn(c,o,own,paint,label);}finally{c.RestoreToCount(count);for(const r of resources.reverse())r?.Dispose?.();}};
  const extraInstances=new Map();
  const getExtra=(source,key,weight)=>{weight=Math.min(900,Math.max(100,Math.round(weight??500)));const current=extraInstances.get(key);if(current?.weight===weight)return current.face;const face=source.Clone(new S.SKFontArguments().SetVariationDesignPosition({wght:weight}));current?.face.Dispose();extraInstances.set(key,{weight,face});return face;};
  const tableView=(face,tag)=>{const bytes=face.GetTableData(tag);return new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);};
  const scenes=[
    {id:'variations',group:'Fonts & text',title:'Variable typography',tag:'Real font instances',description:'Move the weight control to create actual static font outlines and advances from a WOFF2 variable font.',code:'const face = SKTypeface.FromData(woff2Bytes);\nconst args = new SKFontArguments()\n  .SetVariationDesignPosition({wght: 800});\nconst bold = face.Clone(args);\ncanvas.DrawText("Shape matters.", 50, 210,\n  new SKFont(bold, 78), paint);',draw:draw((c,o,own,p,label)=>{const selected=getFace(o.weight),font=own(new S.SKFont(selected,82)),normal=own(new S.SKFont(variable,82));label('VARIABLE FONT / ROBOTO FLEX',48,56,14);label(`Weight ${currentWeight} · native glyphs, paths and advances`,48,105,25,'#E7F4F8');c.DrawText(o.text||'Shape matters.',48,232,font,p('#30DEAB'));c.DrawText(o.text||'Shape matters.',48,360,normal,p('#69849B'));label('Selected instance',48,275);label('Default weight 400',48,403);const axis=variable.GetVariationDesignParameters()[0];label(`${axis.TagName}   ${axis.Min} — ${axis.Max}`,48,470,20,'#D4A3FF');label(`Text width ${font.MeasureText(o.text||'Shape matters.').toFixed(1)} px`,48,525);})},
    {id:'colorfonts',group:'Fonts & text',title:'Color font palettes',tag:'COLR · CPAL · native rendering',description:'Palette selection changes the embedded CPAL data. Individual color layers are also available as vector glyphs.',code:'const palette = new SKFontArgumentsPalette(1);\nconst face = colorTypeface.Clone(\n  new SKFontArguments().SetPalette(palette));\nconst layers = face.GetColorGlyphLayers(face.GetGlyph(65));\ncanvas.DrawText("A", 80, 300, new SKFont(face, 250), paint);',draw:draw((c,o,own,p,label)=>{const face=getPalette(o.palette),font=own(new S.SKFont(face,270));label('COLOR FONT / PALETTE EXPLORER',48,56,14);c.DrawText('A',90,360,font,p('#FFFFFF'));label('Native COLR glyph',65,415,19,'#E7F4F8');const layers=face.GetColorGlyphLayers(face.GetGlyph(65));for(let i=0;i<layers.length;i++){const x=405+i*200,path=own(font.GetGlyphPath(layers[i].GlyphId));c.Save();c.Translate(x,360);c.DrawPath(path,p(layers[i].Color.ToString()));c.Restore();label(`Layer ${i+1}`,x,415,19,'#E7F4F8');}const colors=face.GetColorPalettes()[0].Colors;for(let i=0;i<colors.length;i++){const paint=own(new S.SKPaint());paint.Color=colors[i];c.DrawRoundRect(S.SKRect.Create(50+i*200,468,155,50),12,12,paint);}label(`Palette ${currentPalette+1} of 2 · two independently addressable layers`,48,562);})},
    {id:'cffoutlines',group:'Fonts & text',title:'CFF2 glyph geometry',tag:'Variable PostScript outlines',description:'CFF2 instances retain native hint programs and exact cubic paths. PDF embedding uses a separate hint-preserving CFF1 conversion.',code:'const face = cff2Typeface.Clone(\n  new SKFontArguments().SetVariationDesignPosition({wght: 700}));\nconst font = new SKFont(face, 360);\nconst path = font.GetGlyphPath(face.GetGlyph(65));\ncanvas.DrawPath(path, paint);',draw:draw((c,o,own,p,label)=>{const face=getCff(o.weight),font=own(new S.SKFont(face,350)),path=own(font.GetGlyphPath(face.GetGlyph(65)));label('CFF2 / CUBIC GLYPH GEOMETRY',48,56,14);label(`Weight ${cffWeight} · ${face.FontFormat} instance`,48,105,24,'#E7F4F8');c.Save();c.Translate(155,420);c.DrawPath(path,p('#173D37'));c.DrawPath(path,p('#30DEAB',2));c.Restore();c.DrawLine(80,420,880,420,p('#43566B',1));label(`Advance ${font.MeasureText('A').toFixed(1)} px`,520,218,23,'#D4A3FF');label(`${path.PointCount} path points`,520,265,20);label('Glyph IDs survive font instancing.',48,510,19,'#E7F4F8');label('Document embedding preserves the same glyph IDs and hints.',48,555);})},
    {id:'fontmetadata',group:'Fonts & text',title:'Font data & formats',tag:'SFNT · WOFF2 · variation axes',description:'Inspect the registered font’s exact tables, variation axis ranges, Unicode coverage, and byte-preserving normalized stream.',code:'const axes = typeface.GetVariationDesignParameters();\nconst positions = typeface.GetVariationDesignPosition();\nconst cmap = typeface.GetTableData("cmap");\nconst unicode = typeface.GetSupportedCodepoints();\nconst sfntBytes = typeface.Serialize();',draw:draw((c,o,own,p,label)=>{const face=getFace(o.weight);label('FONT TABLES / LIVE INSTANCE',48,56,14);label(variable.FamilyName,48,122,38,'#30DEAB');const rows=[['Source','WOFF2 / TrueType variable'],['Selected outline format',face.FontFormat],['Glyphs',String(face.GlyphCount)],['Unicode codepoints',String(face.GetSupportedCodepoints().length)],['Units per em',String(face.UnitsPerEm)],['Serialized font',`${face.Serialize().length.toLocaleString()} bytes`],['Selected variation',`wght = ${currentWeight}`]];rows.forEach(([key,value],i)=>{const y=185+i*43;label(key,50,y,17);label(value,350,y,18,'#E7F4F8');c.DrawLine(48,y+15,900,y+15,p('#263B4E',1));});label(`Tables   ${face.GetTableTags().map(t=>String.fromCharCode(t>>>24,(t>>>16)&255,(t>>>8)&255,t&255)).join(' · ')}`,48,555,12,'#D4A3FF');})}
  ];
  scenes.push(
    {id:'variablelayout',group:'Fonts & text',title:'Variable layout & metrics',tag:'Kerning · Marks · Alternate glyphs',description:'Weight changes kerning, accent anchors, alternate glyph selection, global font metrics, and vertical advances in the native font.',code:'const face = variableFace.Clone(new SKFontArguments()\n  .SetVariationDesignPosition({wght: 900}));\nconst font = new SKFont(face, 100);\ncanvas.DrawShapedText("A\\u0301V", 50, 200, font, paint);\nconst metrics = font.Metrics;\nconst verticalTable = face.GetTableData("vmtx");',draw:draw((c,o,own,p,label)=>{const weight=Math.min(900,Math.max(100,Math.round(o.weight??500))),face=getExtra(metrics,'layout',weight),font=own(new S.SKFont(face,100)),regular=own(new S.SKFont(metrics,100));label('VARIABLE LAYOUT / METRIC RESOLUTION',48,56,14);label(`Weight ${weight} · selected design`,48,106,25,'#E7F4F8');c.DrawShapedText('A\u0301V A\u0301V',48,255,font,p('#30DEAB'),{width:850});c.DrawLine(48,257,900,257,p('#43566B',1));c.DrawShapedText('A\u0301V A\u0301V',48,392,regular,p('#69849B'),{width:850});label('Default weight 100',48,432,15);const vm=tableView(face,'vmtx'),vh=tableView(face,'vhea'),gid=face.GetGlyph(65),adv=vm.getUint16(Math.min(gid,vh.getUint16(34)-1)*4);label(`x-height ${font.Metrics.XHeight.toFixed(1)} px`,48,495,18,'#D4A3FF');label(`Vertical advance ${adv} font units`,380,495,18,'#D4A3FF');label('The wider alternate A appears above weight 580; accents follow its anchors.',48,553,16);})},
    {id:'variablecolor',group:'Fonts & text',title:'Variable color glyphs',tag:'COLRv1 gradients & opacity',description:'Move weight to change the actual gradient endpoint and stop opacity inside a color font; compare default and maximum designs.',code:'const face = colorFont.Clone(new SKFontArguments()\n  .SetVariationDesignPosition({wght: 700}));\nconst graph = face.GetColorGlyphPaint(face.GetGlyph(65));\ncanvas.DrawText("A", 100, 350, new SKFont(face, 300), paint);',draw:draw((c,o,own,p,label)=>{const weight=Math.min(900,Math.max(100,Math.round(o.weight??500))),selected=getExtra(variableColor,'color',weight),maximum=getExtra(variableColor,'colorMax',900);label('VARIABLE COLOR FONT / LIVE PAINT DATA',48,56,14);label(`Weight ${weight} · gradient and alpha`,48,105,25,'#E7F4F8');[variableColor,selected,maximum].forEach((face,i)=>{const x=100+i*300,font=own(new S.SKFont(face,310));c.DrawRoundRect(S.SKRect.Create(x-30,155,220,260),18,18,p('#172A3B'));c.DrawText('A',x,382,font,p('#FFFFFF'));label(['Default 100',`Selected ${weight}`,'Maximum 900'][i],x-15,451,18,'#E7F4F8');});const graph=selected.GetColorGlyphPaint(selected.GetGlyph(65));label(`Gradient endpoint ${graph.Paint.X1} units`,48,512,19,'#D4A3FF');label(`First-stop opacity ${(graph.Paint.ColorLine.Stops[0].Alpha*100).toFixed(0)}%`,480,512,19,'#D4A3FF');label('Static resolved font bytes drive the same native color-glyph renderer.',48,557,16);})}
  );
  // Adds font-hints and font-cache scenes with native font data.
  const fidelity=await createFontFidelityScenes(S,{loadBytes});scenes.push(...fidelity.scenes);
  return {scenes,Dispose(){fidelity.Dispose();currentFace?.Dispose();currentCff?.Dispose();paletteFace?.Dispose();for(const entry of extraInstances.values())entry.face.Dispose();extraInstances.clear();variable.Dispose();color.Dispose();cff.Dispose();metrics.Dispose();variableColor.Dispose();}};
}
